  },
  "4185": {
    "document_id": "4185",
    "label": "1",
    "explanation": "The press release states that Senator Clinton introduced the Hudson-Fulton-Champlain Quadricentennial Commemoration Commission Act of 2006 and that the senators are urging a hearing on the bill. This explicitly connects Clinton to the authorship and advancement of legislation, which qualifies as credit-claiming under the clarification: 'Classify as credit-claiming when the release explicitly connects the senator to an accomplishment or effort in a way that invites credit.'"
  },
  "4559": {
    "document_id": "4559",
    "label": "1",
    "explanation": "The press release states that Senators Collins and Snowe 'have secured $2.5 million for this project over the last two fiscal years and have requested more funding for FY 2007.' This explicitly connects the senators to securing funding for the Penobscot River Restoration Project, which qualifies as credit-claiming under the clarification: 'Classify as credit-claiming when the release explicitly connects the senator to an accomplishment or effort in a way that invites credit.'"
  }
}

